'use strict';

// MAIN //

/**
* Builds lookup state from validated index rows.
*
* @param {Object} index - data index
* @returns {Object} repository state
*/
function buildState( index ) {
	var sourceHashes = new Map();
	var libraryHashes = new Map();
	var freshness = new Map();
	var sourceProjectIds = new Map();

	index.records.forEach( function addRow( row ) {
		var sourceKey = row.library_id + '/' + row.source_id;
		var libraryHashKey = row.library_id + '/' + row.report_sha256;
		var freshnessKey = sourceKey + '/' + row.variant_key;
		var previous = freshness.get( freshnessKey );
		var priorProjectId;

		if ( !sourceHashes.has( sourceKey ) ) {
			sourceHashes.set( sourceKey, new Set() );
		}
		sourceHashes.get( sourceKey ).add( row.report_sha256 );
		if ( !libraryHashes.has( libraryHashKey ) ) {
			libraryHashes.set( libraryHashKey, new Set() );
		}
		libraryHashes.get( libraryHashKey ).add( row.source_id );
		if ( !previous || Date.parse( row.timestamp ) > Date.parse( previous ) ) {
			freshness.set( freshnessKey, row.timestamp );
		}
		if ( row.origin.type === 'ci_artifact' ) {
			priorProjectId = sourceProjectIds.get( sourceKey );
			if ( priorProjectId && priorProjectId !== row.origin.project.id ) {
				throw new Error( 'Source ' + sourceKey + ' contains multiple immutable project IDs' );
			}
			sourceProjectIds.set( sourceKey, row.origin.project.id );
		}
	} );
	return {
		'sourceHashes': sourceHashes,
		'libraryHashes': libraryHashes,
		'freshness': freshness,
		'sourceProjectIds': sourceProjectIds
	};
}


// EXPORTS //

module.exports = buildState;
